import pypdf,re
for i in [2,3]:
    t=' '.join(p.extract_text() for p in pypdf.PdfReader(f'studies/papers/paper_{i}.pdf').pages)
    print('#####',i)
    for k in ['hydroxytamoxifen','4-OHT','OHT','OH-Tam','24 h','48 h','72 h','hours']:
        for m in re.finditer(re.escape(k),t):
            print(k,':',t[max(0,m.start()-200):m.start()+200].replace('\n',' '));print('--')

